{#- Code generated by authfly/codegen from specs/widgets/notice.def.ts. DO NOT EDIT.
    Authfly notice on UI8Kit 3 primitives: check email, verified, link error, sign out (form). Props as xgen. -#}
{%- import 'authfly/components.html.j2' as af -%}
{%- set id = p.id or '' -%}{%- set l = p.labels or {} -%}{%- set error = p.error or '' -%}
{%- set formError = id ~ '-error' if error else none -%}
{%- set isError = (p.tone or 'default') == 'error' -%}
{%- set c3 -%}
{{ af.icon_badge(p.icon or 'mail-check', 'destructive' if isError else 'default') }}
{%- set c1 -%}{%- if p.detail or '' -%}
{{ af.text('', 'text-sm font-semibold text-foreground', {'data-testid': 'detail'}, af_esc(p.detail or '')) }}
{%- endif -%}{%- endset -%}
{{ af.head(id, p.title or '', p.text or '', 'center', 'alert' if isError else 'status', c1) }}
{%- if (p.action or 'link') == 'form' -%}
{%- set c2 -%}{{ af.hidden('csrf', p.csrf or '') }}
{{ af.button('', 'submit', af_skin('button', 'default', 'w-full'), {'data-testid': 'submit'}, af_esc(l.cta or '')) }}{%- endset -%}
{{ af.form(p.actionUrl or '', 'w-full', {'data-testid': 'authfly-form'}, c2) }}
{%- else -%}
{{ af.button(l.ctaHref or '', '', af_skin('button', 'default', 'w-full'), {'data-testid': 'cta'}, af_esc(l.cta or '')) }}
{%- endif -%}
{%- if l.secondary or '' -%}
{{ af.link(l.secondaryHref or '', af_skin('link', 'text-sm'), 'secondary', l.secondary or '') }}
{%- endif -%}
{%- endset -%}
{{ af.card(af_skin('widgetCard', 'items-center text-center'), {'data-testid': 'authfly-notice', 'data-tone': p.tone or 'default', 'aria-labelledby': none if p.landmarkLabel else id ~ '-title', 'aria-label': p.landmarkLabel or none}, c3) }}
